import{_ as p,a0 as l,w as o,s as c,ao as r,I as t,x as n,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Linux 上记录和重放终端会话活动 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上记录和重放终端会话活动 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上记录和重放终端会话活动 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上记录和重放终端会话活动 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190701 Learn how to Record and Replay Linux Terminal Sessions Activity","title":"在 Linux 上记录和重放终端会话活动","tag":"201910","desc":""},"relativePath":"201910/20190701 Learn how to Record and Replay Linux Terminal Sessions Activity.md","filePath":"[post].md"}'),d={name:"201910/20190701 Learn how to Record and Replay Linux Terminal Sessions Activity.md"};function h(u,s,g,k,x,b){const a=l("Link");return o(),c("div",null,[s[15]||(s[15]=r(`<h1 id="在-linux-上记录和重放终端会话活动" tabindex="-1">在 Linux 上记录和重放终端会话活动 <a class="header-anchor" href="#在-linux-上记录和重放终端会话活动" aria-label="Permalink to “在 Linux 上记录和重放终端会话活动”">​</a></h1><p>通常，Linux 管理员们都使用 <code>history</code> 命令来跟踪在先前的会话中执行过哪些命令，但是 <code>history</code> 命令的局限性在于它不存储命令的输出。在某些情况下，我们要检查上一个会话的命令输出，并希望将其与当前会话进行比较。除此之外，在某些情况下，我们正在对 Linux 生产环境中的问题进行故障排除，并希望保存所有终端会话活动以供将来参考，因此在这种情况下，<code>script</code> 命令就变得很方便。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201910/06/122659mmi64z8ryr4z2n8a.jpg" alt=""></p><p><code>script</code> 是一个命令行工具，用于捕获/记录你的 Linux 服务器终端会话活动，以后可以使用 <code>scriptreplay</code> 命令重放记录的会话。在本文中，我们将演示如何安装 <code>script</code> 命令行工具以及如何记录 Linux 服务器终端会话活动，然后，我们将看到如何使用 <code>scriptreplay</code> 命令来重放记录的会话。</p><h3 id="安装-script-工具" tabindex="-1">安装 script 工具 <a class="header-anchor" href="#安装-script-工具" aria-label="Permalink to “安装 script 工具”">​</a></h3><h4 id="在-rhel-7-centos-7-上安装-script-工具" tabindex="-1">在 RHEL 7/ CentOS 7 上安装 script 工具 <a class="header-anchor" href="#在-rhel-7-centos-7-上安装-script-工具" aria-label="Permalink to “在 RHEL 7/ CentOS 7 上安装 script 工具”">​</a></h4><p><code>script</code> 命令由 RPM 包 <code>util-linux</code> 提供，如果你没有在你的 CentOS 7 / RHEL 7 系统上安装它，运行下面的 <code>yum</code> 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# yum install util-linux -y</span></span></code></pre></div><h4 id="在-rhel-8-centos-8-上安装-script-工具" tabindex="-1">在 RHEL 8 / CentOS 8 上安装 script 工具 <a class="header-anchor" href="#在-rhel-8-centos-8-上安装-script-工具" aria-label="Permalink to “在 RHEL 8 / CentOS 8 上安装 script 工具”">​</a></h4><p>运行下面的 <code>dnf</code> 命令来在 RHEL 8 / CentOS 8 上安装 <code>script</code> 工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install util-linux -y</span></span></code></pre></div><h4 id="在基于-debian-的系统-ubuntu-linux-mint-上安装-script-工具" tabindex="-1">在基于 Debian 的系统（Ubuntu / Linux Mint）上安装 script 工具 <a class="header-anchor" href="#在基于-debian-的系统-ubuntu-linux-mint-上安装-script-工具" aria-label="Permalink to “在基于 Debian 的系统（Ubuntu / Linux Mint）上安装 script 工具”">​</a></h4><p>运行下面的 <code>apt-get</code> 命令来安装 <code>script</code> 工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]# apt-get install util-linux -y</span></span></code></pre></div><h3 id="如何使用-script-工具" tabindex="-1">如何使用 script 工具 <a class="header-anchor" href="#如何使用-script-工具" aria-label="Permalink to “如何使用 script 工具”">​</a></h3><p>直接使用 <code>script</code> 命令，在终端上键入 <code>script</code> 命令，然后按回车，它将开始在名为 <code>typescript</code> 的文件中捕获当前的终端会话活动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# script</span></span>
<span class="line"><span>Script started, file is typescript</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>要停止记录会话活动，请键入 <code>exit</code> 命令，然后按回车：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# exit</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span>Script done, file is typescript</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p><code>script</code> 命令的语法格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~] # script {options}  {file_name}</span></span></code></pre></div><p>能在 <code>script</code> 命令中使用的不同选项：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/options-script-command.png" alt="options-script-command"></p><p>让我们开始通过执行 <code>script</code> 命令来记录 Linux 终端会话，然后执行诸如 <code>w</code>，<code>route -n</code>，<code>df -h</code> 和 <code>free -h</code>，示例如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/script-examples-linux-server-1024x736.jpg" alt="script-examples-linux-server"></p><p>正如我们在上面看到的，终端会话日志保存在文件 <code>typescript</code> 中：</p><p>现在使用 <code>cat</code> / <code>vi</code> 命令查看 <code>typescript</code> 文件的内容，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ls -l typescript</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 1861 Jun 21 00:50 typescript</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/typescript-file-content-linux-1024x794.jpg" alt="typescript-file-content-linux"></p><p>以上内容确认了我们在终端上执行的所有命令都已保存在 <code>typescript</code> 文件中。</p><h3 id="在-script-命令中使用定制文件名" tabindex="-1">在 script 命令中使用定制文件名 <a class="header-anchor" href="#在-script-命令中使用定制文件名" aria-label="Permalink to “在 script 命令中使用定制文件名”">​</a></h3><p>假设我们要使用自定义文件名来执行 <code>script</code> 命令，可以在 <code>script</code> 命令后指定文件名。在下面的示例中，我们使用的文件名为 <code>session-log-(当前日期时间).txt</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# script sessions-log-$(date +%d-%m-%Y-%T).txt</span></span>
<span class="line"><span>Script started, file is sessions-log-21-06-2019-01:37:39.txt</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>现在运行该命令并输入 <code>exit</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# exit</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span>Script done, file is sessions-log-21-06-2019-01:37:39.txt</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="附加命令输出到-script-记录文件" tabindex="-1">附加命令输出到 script 记录文件 <a class="header-anchor" href="#附加命令输出到-script-记录文件" aria-label="Permalink to “附加命令输出到 script 记录文件”">​</a></h3><p>假设 <code>script</code> 命令已经将命令输出记录到名为 <code>session-log.txt</code> 的文件中，现在我们想将新会话命令的输出附加到该文件中，那么可以在 <code>script</code> 命令中使用 <code>-a</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# script -a sessions-log.txt</span></span>
<span class="line"><span>Script started, file is sessions-log.txt</span></span>
<span class="line"><span>[root@linuxtechi ~]# xfs_info /dev/mapper/centos-root</span></span>
<span class="line"><span>meta-data=/dev/mapper/centos-root isize=512    agcount=4, agsize=2746624 blks</span></span>
<span class="line"><span>         =                       sectsz=512   attr=2, projid32bit=1</span></span>
<span class="line"><span>         =                       crc=1        finobt=0 spinodes=0</span></span>
<span class="line"><span>data     =                       bsize=4096   blocks=10986496, imaxpct=25</span></span>
<span class="line"><span>         =                       sunit=0      swidth=0 blks</span></span>
<span class="line"><span>naming   =version 2              bsize=4096   ascii-ci=0 ftype=1</span></span>
<span class="line"><span>log      =internal               bsize=4096   blocks=5364, version=2</span></span>
<span class="line"><span>         =                       sectsz=512   sunit=0 blks, lazy-count=1</span></span>
<span class="line"><span>realtime =none                   extsz=4096   blocks=0, rtextents=0</span></span>
<span class="line"><span>[root@linuxtechi ~]# exit</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span>Script done, file is sessions-log.txt</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>要查看更新的会话记录，使用 <code>cat session-log.txt</code> 命令。</p><h3 id="无需-shell-交互而捕获命令输出到-script-记录文件" tabindex="-1">无需 shell 交互而捕获命令输出到 script 记录文件 <a class="header-anchor" href="#无需-shell-交互而捕获命令输出到-script-记录文件" aria-label="Permalink to “无需 shell 交互而捕获命令输出到 script 记录文件”">​</a></h3><p>假设我们要捕获命令的输出到会话记录文件，那么使用 <code>-c</code> 选项，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# script -c &quot;uptime &amp;&amp; hostname &amp;&amp; date&quot; root-session.txt</span></span>
<span class="line"><span>Script started, file is root-session.txt</span></span>
<span class="line"><span> 01:57:40 up  2:30,  3 users,  load average: 0.00, 0.01, 0.05</span></span>
<span class="line"><span>linuxtechi</span></span>
<span class="line"><span>Fri Jun 21 01:57:40 EDT 2019</span></span>
<span class="line"><span>Script done, file is root-session.txt</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="以静默模式运行-script-命令" tabindex="-1">以静默模式运行 script 命令 <a class="header-anchor" href="#以静默模式运行-script-命令" aria-label="Permalink to “以静默模式运行 script 命令”">​</a></h3><p>要以静默模式运行 <code>script</code> 命令，请使用 <code>-q</code> 选项，该选项将禁止 <code>script</code> 的启动和完成消息，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# script -c &quot;uptime &amp;&amp; date&quot; -q root-session.txt</span></span>
<span class="line"><span> 02:01:10 up  2:33,  3 users,  load average: 0.00, 0.01, 0.05</span></span>
<span class="line"><span>Fri Jun 21 02:01:10 EDT 2019</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>要将时序信息记录到文件中并捕获命令输出到单独的文件中，这可以通过在 <code>script</code> 命令中传递时序文件（<code>-timing</code>）实现，示例如下所示：</p><p>语法格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~ ]# script -t &lt;timing-file-name&gt;  {file_name}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# script --timing=timing.txt session.log</span></span>
<span class="line"><span>Script started, file is session.log</span></span>
<span class="line"><span>[root@linuxtechi ~]# uptime</span></span>
<span class="line"><span> 02:27:59 up  3:00,  3 users,  load average: 0.00, 0.01, 0.05</span></span>
<span class="line"><span>[root@linuxtechi ~]# date</span></span>
<span class="line"><span>Fri Jun 21 02:28:02 EDT 2019</span></span>
<span class="line"><span>[root@linuxtechi ~]# free -h</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3.9G        171M        2.0G        8.6M        1.7G        3.3G</span></span>
<span class="line"><span>Swap:          3.9G          0B        3.9G</span></span>
<span class="line"><span>[root@linuxtechi ~]# whoami</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>[root@linuxtechi ~]# exit</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span>Script done, file is session.log</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span>
<span class="line"><span>[root@linuxtechi ~]# ls -l session.log timing.txt</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 673 Jun 21 02:28 session.log</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 414 Jun 21 02:28 timing.txt</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="重放记录的-linux-终端会话活动" tabindex="-1">重放记录的 Linux 终端会话活动 <a class="header-anchor" href="#重放记录的-linux-终端会话活动" aria-label="Permalink to “重放记录的 Linux 终端会话活动”">​</a></h3><p>现在，使用 <code>scriptreplay</code> 命令重放录制的终端会话活动。</p><p>注意：<code>scriptreplay</code> 也由 RPM 包 <code>util-linux</code> 提供。<code>scriptreplay</code> 命令需要时序文件才能工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# scriptreplay --timing=timing.txt session.log</span></span></code></pre></div><p>上面命令的输出将如下所示，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/scriptreplay-linux.gif" alt=""></p><h3 id="记录所有用户的-linux-终端会话活动" tabindex="-1">记录所有用户的 Linux 终端会话活动 <a class="header-anchor" href="#记录所有用户的-linux-终端会话活动" aria-label="Permalink to “记录所有用户的 Linux 终端会话活动”">​</a></h3><p>在某些关键业务的 Linux 服务器上，我们希望跟踪所有用户的活动，这可以使用 <code>script</code> 命令来完成，将以下内容放在 <code>/etc/profile</code> 文件中，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# vi /etc/profile</span></span>
<span class="line"><span>……………………………………………………</span></span>
<span class="line"><span>if [ &quot;x$SESSION_RECORD&quot; = &quot;x&quot; ]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>timestamp=$(date +%d-%m-%Y-%T)</span></span>
<span class="line"><span>session_log=/var/log/session/session.$USER.$$.$timestamp</span></span>
<span class="line"><span>SESSION_RECORD=started</span></span>
<span class="line"><span>export SESSION_RECORD</span></span>
<span class="line"><span>script -t -f -q 2&gt;\${session_log}.timing $session_log</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>……………………………………………………</span></span></code></pre></div><p>保存文件并退出。</p><p>在 <code>/var/log</code> 文件夹下创建 <code>session</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# mkdir /var/log/session</span></span></code></pre></div><p>给该文件夹指定权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# chmod 777 /var/log/session/</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>现在，验证以上代码是否有效。在我正在使用 <code>pkumar</code> 用户的情况下，登录普通用户到 Linux 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~ ] # ssh root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>[root@linuxtechi ~]$ uptime</span></span>
<span class="line"><span> 04:34:09 up  5:06,  3 users,  load average: 0.00, 0.01, 0.05</span></span>
<span class="line"><span>[root@linuxtechi ~]$ date</span></span>
<span class="line"><span>Fri Jun 21 04:34:11 EDT 2019</span></span>
<span class="line"><span>[root@linuxtechi ~]$ free -h</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3.9G        172M        2.0G        8.6M        1.7G        3.3G</span></span>
<span class="line"><span>Swap:          3.9G          0B        3.9G</span></span>
<span class="line"><span>[root@linuxtechi ~]$ id</span></span>
<span class="line"><span>uid=1001(pkumar) gid=1002(pkumar) groups=1002(pkumar) context=unconfined_u:unconfined_r:unconfined_t:s0-s0:c0.c1023</span></span>
<span class="line"><span>[root@linuxtechi ~]$ whoami</span></span>
<span class="line"><span>pkumar</span></span>
<span class="line"><span>[root@linuxtechi ~]$ exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Login as root and view user’s linux terminal session activity</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@linuxtechi ~]# cd /var/log/session/</span></span>
<span class="line"><span>[root@linuxtechi session]# ls -l | grep pkumar</span></span>
<span class="line"><span>-rw-rw-r--. 1 pkumar pkumar 870 Jun 21 04:34 session.pkumar.19785.21-06-2019-04:34:05</span></span>
<span class="line"><span>-rw-rw-r--. 1 pkumar pkumar 494 Jun 21 04:34 session.pkumar.19785.21-06-2019-04:34:05.timing</span></span>
<span class="line"><span>[root@linuxtechi session]#</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Session-output-file-linux-1024x353.jpg" alt="Session-output-file-linux"></p><p>我们还可以使用 <code>scriptreplay</code> 命令来重放用户的终端会话活动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi session]# scriptreplay --timing session.pkumar.19785.21-06-2019-04\\:34\\:05.timing session.pkumar.19785.21-06-2019-04\\:34\\:05</span></span></code></pre></div><p>以上就是本教程的全部内容，请在下面的评论部分中分享你的反馈和评论。</p><hr>`,70)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),i(a,{href:"https://www.linuxtechi.com/record-replay-linux-terminal-sessions-activity/"},{default:e(()=>[...s[0]||(s[0]=[n("https://www.linuxtechi.com/record-replay-linux-terminal-sessions-activity/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=n("作者：",-1)),i(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[2]||(s[2]=[n("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const v=p(d,[["render",h]]);export{y as __pageData,v as default};
